import{_ as a,o,c as i,a2 as t}from"./chunks/framework.CqGPl1zp.js";const r="/newx-doc/assets/%E5%B7%A5%E4%BD%9C%E5%8F%B0.DdWaOBKD.png",c="/newx-doc/assets/%E6%89%93%E5%8D%A1.LuO9qkeB.png",_=JSON.parse('{"title":"移动端 HRM","description":"","frontmatter":{},"headers":[],"relativePath":"hrm/mobile.md","filePath":"hrm/mobile.md","lastUpdated":null}'),d={name:"hrm/mobile.md"};function l(n,e,p,s,h,u){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="移动端-hrm" tabindex="-1">移动端 HRM <a class="header-anchor" href="#移动端-hrm" aria-label="Permalink to &quot;移动端 HRM&quot;">​</a></h1><p>友情提示</p><p>本文讲解 yudao 移动端（uni-app 版）的 HRM 系统，重点说清楚两件事：HRM 模块<strong>已经提供手机端</strong>、当前支持的<strong>主要功能</strong>。</p><ul><li>仓库：<a href="https://github.com/yudaocode/yudao-ui-admin-uniapp" target="_blank" rel="noreferrer">https://github.com/yudaocode/yudao-ui-admin-uniapp</a>，基于 <code>uni-app</code> + <code>Vue3</code> + <code>wot-ui</code> 实现，支持 H5、微信小程序等多端。</li><li>后端：复用 PC 端同一套 <code>yudao-module-hrm</code> 模块与 <code>/hrm/**</code> 接口，移动端只是换了一层 UI。</li></ul><h2 id="_1-移动端功能" tabindex="-1">1. 移动端功能 <a class="header-anchor" href="#_1-移动端功能" aria-label="Permalink to &quot;1. 移动端功能&quot;">​</a></h2><p>移动端按「管理端 + 员工端」两条线组织，菜单分组与 PC 端保持一致：</p><ul><li>工作台：HR 工作台、团队工作台。</li><li>组织与员工：组织架构、员工档案、员工设置。</li><li>招聘管理：候选人、招聘职位、招聘渠道、淘汰原因。</li><li>考勤管理：打卡记录、请假记录、月度汇总、考勤组设置、节假日设置。</li><li>社保管理：社保表、社保方案。</li><li>薪资管理：月度工资表、历史工资表、薪资档案、发放记录，以及薪资组、计税规则、计薪设置、工资表设置、调薪模板等配置。</li><li>绩效管理：KPI 考核、绩效档案、考核指标模板、考核结果设置。</li><li>HRM 员工端：个人工作台、我的档案、我的社保、我的工资条、<strong>打卡</strong>、考勤报表、KPI 考核、我的绩效档案。</li></ul><p><img src="'+r+'" alt="HRM 移动端"></p><p>其中<strong>打卡是移动端独有的功能</strong>，PC 端员工端只能查看打卡记录，详见下一节。</p><h2 id="_2-员工打卡" tabindex="-1">2. 员工打卡 <a class="header-anchor" href="#_2-员工打卡" aria-label="Permalink to &quot;2. 员工打卡&quot;">​</a></h2><p>对应 [HRM 人力资源 -&gt; HRM 员工端 -&gt; 打卡] 菜单，页面在 <code>pages-hrm/portal/attendance/clock/</code> 目录，由 HrmPortalAttendanceClockController 提供接口（<code>/hrm/portal/attendance/clock</code>）。</p><p>页面底部分「打卡」和「统计」两个页签：前者由 <code>clock-panel.vue</code> 完成当日打卡，后者由 <code>statistics-panel.vue</code> 展示本月考勤汇总。</p><p><img src="'+c+'" alt="HRM 员工端 - 打卡"></p><h3 id="_2-1-打卡流程" tabindex="-1">2.1 打卡流程 <a class="header-anchor" href="#_2-1-打卡流程" aria-label="Permalink to &quot;2.1 打卡流程&quot;">​</a></h3><p>进入页面时调用 <code>get-detail</code> 获取当日打卡详情：所属考勤组、班次时点、是否休息日、考勤组配置的打卡地点与 WiFi、当日打卡时间线，以及<strong>下一次该打的卡</strong>（上班还是下班）。</p><p>点击打卡按钮后，前端先做设备校验，再调用 <code>create</code> 提交，请求体携带定位地址、经纬度和 WiFi 的 <code>ssid</code>、<code>mac</code>。打卡成功后刷新时间线，写入的记录 <code>source_type = 1</code>（手机端）。</p><p>按钮文案会跟着 <code>nextClock.buttonStatus</code> 变化，区分正常打卡、迟到打卡、早退打卡和更新打卡；休息日则提示「今日休息，无需打卡」。</p><h3 id="_2-2-定位与-wifi-校验" tabindex="-1">2.2 定位与 WiFi 校验 <a class="header-anchor" href="#_2-2-定位与-wifi-校验" aria-label="Permalink to &quot;2.2 定位与 WiFi 校验&quot;">​</a></h3><p>校验规则来自考勤组的开关，两者可以同时开启：</p><ul><li><strong>定位打卡</strong>（<code>open_point_card</code>）：读取当前定位，按考勤组配置的经纬度和 <code>radius</code> 半径逐个比对，只要落在任一地点范围内即视为有效；否则提示「当前不在考勤范围」。</li><li><strong>WiFi 打卡</strong>（<code>open_wifi_card</code>）：读取当前连接的 WiFi，<strong>MAC 或 SSID 命中任一配置项</strong>即可，比对时会去掉 SSID 两端的引号、忽略 MAC 的分隔符和大小写。</li></ul><p>考勤组的定位、WiFi 配置详见 <a href="./attendance">《【考勤】考勤管理》</a>。</p><p>WiFi 打卡的端限制</p><p>读取 WiFi 信息依赖运行环境：<strong>H5 端无法获取 WiFi</strong>，此时页面会提示「当前端不支持读取 WiFi，请使用支持的 App 或微信小程序打卡」。因此启用了 WiFi 打卡的企业，需要引导员工用 App 或小程序，不要只发 H5 链接。</p><p>其它与 PC 端的差异</p><p>除打卡外，部分重编排类操作仍建议在 PC 端完成，例如工资表在线编辑、工资条模板的分类拖拽。</p><h2 id="_3-启动与发布" tabindex="-1">3. 启动与发布 <a class="header-anchor" href="#_3-启动与发布" aria-label="Permalink to &quot;3. 启动与发布&quot;">​</a></h2><ul><li>启动：参考 <a href="./../quick-start-front">《快速启动【前端】》</a> 文档的「1.4 Vue3 + uni-app 版本」小节。</li><li>发布：参考 <a href="./../admin-uniapp/deploy">《运行发布》</a> 文档。</li></ul><p>启动完成后，在工作台选择「HRM 人力资源」即可进入。</p><p>别忘了先开启 HRM 模块</p><p>移动端复用后端同一套接口，因此 <a href="./build">《功能开启》</a> 里的模块启用和 SQL 导入同样是前提；菜单可见性也由 <code>hrm:**</code> 权限控制。</p><h2 id="_4-代码位置" tabindex="-1">4. 代码位置 <a class="header-anchor" href="#_4-代码位置" aria-label="Permalink to &quot;4. 代码位置&quot;">​</a></h2><ul><li>页面：<code>src/pages-hrm/</code>、<code>src/pages-statistics/hrm/</code></li><li>接口：<code>src/api/hrm/</code></li><li>菜单：<code>src/pages/index/menu.json</code> 的 <code>hrm</code> 分组</li></ul>',32)])])}const g=a(d,[["render",l]]);export{_ as __pageData,g as default};
